mapper.select:
select s.*, stu.name as student_name
from t_score s
         left join t_student stu on s.student_id = stu.id
where s.exam_id = #{examId}
  and s.class_id = #{classId}
  and s.course_id = #{courseId}
order by s.score desc

SELECT
ROUND(AVG(score), 6) AS avg_score,   -- 平均分
MAX(score) AS max_score,             -- 最高分
MIN(score) AS min_score,             -- 最低分
-- 及格率：及格人数 / 总人数，保留6位小数
ROUND(SUM(CASE WHEN score >= 60 THEN 1 ELSE 0 END) / COUNT(*), 6) AS pass_rate
FROM t_score
WHERE exam_id = #{examId}
AND class_id = #{classId}
AND course_id = #{courseId}

select student_id, sum(score) as total_score
from t_score
where exam_id = #{examId}
  and class_id = #{classId}
group by student_id
order by total_score desc

mapper.update:
update t_score
set score = #{score}
where id = #{id}
